namespace Reforged.Server;
public sealed record RuntimeSecurityPolicySmokeReport(bool Passed,IReadOnlyList<string> Checks,IReadOnlyList<string> Failures){public string ToJson()=>JsonSerializer.Serialize(this,new JsonSerializerOptions{WriteIndented=true});public static RuntimeSecurityPolicySmokeReport Run(){var c=new List<string>();var f=new List<string>();void Check(bool x,string n){c.Add(n);if(!x)f.Add(n);}var service=new RuntimeSecurityPolicyService(16);var resource=new RuntimeSecurityResource("door-100","Doors",RuntimeTrustBoundary.Player,new HashSet<RuntimeSecurityOperation>{RuntimeSecurityOperation.Read,RuntimeSecurityOperation.Execute},true,true);var player=new RuntimeSecurityPrincipal("char-1",RuntimeTrustBoundary.Player,new HashSet<string>{"player"},new HashSet<string>{"Doors:door-100:Read"},true);RuntimeSecurityRequest Req(RuntimeSecurityPrincipal p,RuntimeSecurityOperation op,IReadOnlyDictionary<string,string>? input=null)=>new("req-1",p,resource,op,null,null,input??new Dictionary<string,string>());Check(service.Authorize(Req(player,RuntimeSecurityOperation.Read)).Allowed,"exact-capability");Check(!service.Authorize(Req(player,RuntimeSecurityOperation.Execute)).Allowed,"missing-capability-denied");var unauth=player with { Authenticated=false };Check(!service.Authorize(Req(unauth,RuntimeSecurityOperation.Read)).Allowed,"authentication-required");var script=player with { PrincipalId="script-1",Boundary=RuntimeTrustBoundary.Script,Capabilities=new HashSet<string>{"Doors:*:Read"} };Check(service.Authorize(Req(script,RuntimeSecurityOperation.Read)).Allowed,"subsystem-capability");var bad=Req(player,RuntimeSecurityOperation.Read,new Dictionary<string,string>{{"text","0123456789abcdefg"}});Check(!service.Authorize(bad).Allowed,"input-length-limit");var normalized=Req(player,RuntimeSecurityOperation.Read,new Dictionary<string,string>{{"text","a\r\nb"}});Check(service.Authorize(normalized).SanitizedInputs["text"]=="a\nb","line-ending-sanitization");var internalPrincipal=player with { PrincipalId="runtime",Boundary=RuntimeTrustBoundary.InternalRuntime,Capabilities=new HashSet<string>() };Check(service.Authorize(Req(internalPrincipal,RuntimeSecurityOperation.Execute)).Allowed,"internal-runtime-boundary");Check(RuntimeSecurityPolicyService.ValidateResource(resource).Count==0,"resource-invariants");return new(f.Count==0,c,f);}}
